(function(){
'use strict';
const C=window.FastooleeImageCore;if(!C)return;
const root=document.querySelector('[data-image-tool]');if(!root)return;
const tool=root.dataset.imageTool, q=(s)=>root.querySelector(s), qa=(s)=>[...root.querySelectorAll(s)];
const file=q('[data-file]'), drop=q('[data-drop]'), run=q('[data-run]'), reset=q('[data-reset]'), err=q('[data-error]'), status=q('[data-status]'), orig=q('[data-original]'), result=q('[data-result]'), preview=q('[data-result-preview]'), checklist=q('[data-checklist]'), download=q('[data-download]'), progress=q('[data-progress]');
let source=null,lastBlob=null,lastName='fastoolee-result.jpg',busy=false;
const msg=(t,type='')=>{if(!status)return;status.textContent=t;status.dataset.type=type;};
const error=(t)=>{if(err){err.textContent=t;err.hidden=!t;} if(t)msg(t,'error');};
const val=(name,fallback='')=>{const el=q(`[name="${name}"]`);return el?el.value:fallback;};
const checked=(name)=>{const el=q(`[name="${name}"]`);return !!(el&&el.checked);};
const nval=(name,fallback=0)=>{const n=parseFloat(val(name));return Number.isFinite(n)?n:fallback;};
function setProgress(p,label=''){if(!progress)return;progress.hidden=false;const bar=progress.querySelector('i');if(bar)bar.style.width=Math.max(0,Math.min(100,p))+'%';const span=progress.querySelector('span');if(span&&label)span.textContent=label;}
function hideProgress(){if(progress)progress.hidden=true;}
function originalInfo(){if(!source||!orig)return;const dpi=source.dpi.x?`${source.dpi.x} DPI`:'DPI not embedded';orig.innerHTML=`<strong>Original</strong><span>${source.width} × ${source.height} px</span><span>${C.humanBytes(source.size)}</span><span>${dpi}</span><span>${source.type.replace('image/','').toUpperCase()}</span>`;orig.hidden=false;}
async function loadFile(f){error('');if(source)C.releaseImage(source);source=null;lastBlob=null;if(result)result.hidden=true;try{msg('Reading image…');source=await C.fileToImage(f);originalInfo();msg('Image ready.','ok');syncLive();}catch(e){error(e.message||'Could not read this image.');}}
if(file)file.addEventListener('change',()=>{if(file.files[0])loadFile(file.files[0]);});
if(drop){['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('is-drag');}));['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('is-drag');}));drop.addEventListener('drop',e=>{const f=e.dataTransfer.files&&e.dataTransfer.files[0];if(f){try{file.files=e.dataTransfer.files}catch(_e){}loadFile(f);}});}
function syncLive(){
 if(tool==='physical-resizer'){
  const w=nval('width'),h=nval('height'),u=val('unit','cm'),dpi=nval('dpi',300),out=q('[data-live-size]');if(out&&w>0&&h>0)out.textContent=`${w} × ${h} ${u} at ${dpi} DPI = ${C.unitToPx(w,u,dpi)} × ${C.unitToPx(h,u,dpi)} px`;
 }
 if(tool==='photo-35x45'||tool==='photo-2x2'){
  const dpi=nval('dpi',300),mm=tool==='photo-35x45'?[35,45]:[50.8,50.8],out=q('[data-live-size]');if(out)out.textContent=`${mm[0]} × ${mm[1]} mm · ${C.unitToPx(mm[0],'mm',dpi)} × ${C.unitToPx(mm[1],'mm',dpi)} px · ${dpi} DPI`;
 }
}
qa('input,select').forEach(el=>el.addEventListener('input',syncLive));syncLive();
function outputName(prefix,mime){return `${prefix}-${Date.now()}.${C.extFromMime(mime)}`;}
async function finalize(canvas,mime,dpi,targetBytes,opts,prefix,checks=[]){
 setProgress(72,'Encoding result…');let rec=await C.encodeTarget(canvas,mime,targetBytes,opts);let blob=rec.blob;if(dpi&&(/jpeg|png/.test(mime)))blob=await C.patchDpi(blob,mime,dpi);lastBlob=blob;lastName=outputName(prefix,mime);if(preview)C.previewBlob(blob,preview);if(result){result.hidden=false;result.scrollIntoView({behavior:'smooth',block:'nearest'});}if(checklist){const rows=checks.map(x=>`<li class="${x.ok?'pass':'warn'}"><b>${x.ok?'✓':'!'}</b><span>${x.label}</span></li>`);rows.push(`<li class="${targetBytes&&!rec.reached?'warn':'pass'}"><b>${targetBytes&&!rec.reached?'!':'✓'}</b><span>File size: ${C.humanBytes(blob.size)}${targetBytes?` · target ≤ ${C.humanBytes(targetBytes)}`:''}</span></li>`);checklist.innerHTML=rows.join('');}msg(targetBytes&&!rec.reached?'Best achievable result created. Review the size below.':'Result ready.','ok');setProgress(100,'Done');setTimeout(hideProgress,700);return {blob,rec};
}
async function processUniversal(){
 if(!source)throw new Error('Upload an image first.');const w=nval('width'),h=nval('height');if(w<=0||h<=0)throw new Error('Enter a valid width and height.');const dpi=nval('dpi',300),unit=val('unit','px'),dw=C.unitToPx(w,unit,dpi),dh=C.unitToPx(h,unit,dpi);if(dw<1||dh<1||dw>9000||dh>9000)throw new Error('Output dimensions must be between 1 and 9,000 pixels per side.');
 const mime=C.mimeFromFormat(val('format','keep'),source.type),canvas=C.canvas(dw,dh),ctx=canvas.getContext('2d');C.drawFit(ctx,source.img,dw,dh,val('fit','fit'),mime==='image/jpeg'?'#fff':null);const kb=nval('maxkb');const target=kb>0?kb*1024:null;const manual=val('quality','auto')!=='auto',qv=manual?C.clamp(nval('quality',90)/100,.2,1):.94;return finalize(canvas,mime,dpi,target,{minQuality:.3,maxQuality:qv,allowResize:false},'optimized-image',[{ok:true,label:`Dimensions: ${dw} × ${dh} px`},{ok:true,label:`Format: ${mime.split('/')[1].toUpperCase()}`},{ok:true,label:`DPI: ${dpi}`}]);
}
async function processSignature(){
 if(!source)throw new Error('Upload a signature image first.');const dw=Math.round(nval('width')),dh=Math.round(nval('height'));if(dw<10||dh<10)throw new Error('Enter valid output dimensions.');const mime=C.mimeFromFormat(val('format','png'),source.type),bg=val('background','keep'),canvas=C.canvas(dw,dh),ctx=canvas.getContext('2d');let sr=checked('trim')?C.trimRect(source.img):null;let fill=null;if(bg==='white'||mime==='image/jpeg')fill='#fff';if(fill){ctx.fillStyle=fill;ctx.fillRect(0,0,dw,dh);}C.drawFit(ctx,source.img,dw,dh,'fit',fill,sr);const target=nval('maxkb')*1024||null,dpi=nval('dpi',300);return finalize(canvas,mime,dpi,target,{minQuality:.38,maxQuality:.95,allowResize:false},'signature',[{ok:true,label:`Signature size: ${dw} × ${dh} px`},{ok:true,label:`Empty margins: ${checked('trim')?'trimmed':'kept'}`},{ok:true,label:`Background: ${bg}`}]);
}
async function processPhoto(kind){
 if(!source)throw new Error('Upload a photo first.');const is35=kind==='photo-35x45',dpi=nval('dpi',300),mm=is35?[35,45]:[50.8,50.8],dw=C.unitToPx(mm[0],'mm',dpi),dh=C.unitToPx(mm[1],'mm',dpi),ratio=dw/dh;const zoom=nval('zoom',100)/100,posX=nval('posx',0)/100,posY=nval('posy',0)/100;const sr=C.cropRect(source.width,source.height,ratio,zoom,posX,posY),mime=C.mimeFromFormat(val('format','jpg'),source.type),canvas=C.canvas(dw,dh),ctx=canvas.getContext('2d');C.drawFit(ctx,source.img,dw,dh,'stretch',mime==='image/jpeg'?'#fff':null,sr);return finalize(canvas,mime,dpi,null,{maxQuality:.94},is35?'35x45-photo':'2x2-photo',[{ok:true,label:`Physical size: ${is35?'35 × 45 mm':'2 × 2 inches'}`},{ok:true,label:`Pixels: ${dw} × ${dh}`},{ok:true,label:`Resolution: ${dpi} DPI`}]);
}
async function processPhysical(){
 if(!source)throw new Error('Upload an image first.');const w=nval('width'),h=nval('height'),unit=val('unit','cm'),dpi=nval('dpi',300),dw=C.unitToPx(w,unit,dpi),dh=C.unitToPx(h,unit,dpi);if(dw<1||dh<1||dw>9000||dh>9000)throw new Error('Enter valid physical dimensions.');const mime=C.mimeFromFormat(val('format','jpg'),source.type),canvas=C.canvas(dw,dh),ctx=canvas.getContext('2d');C.drawFit(ctx,source.img,dw,dh,val('fit','fit'),mime==='image/jpeg'?'#fff':null);const target=nval('maxkb')*1024||null;return finalize(canvas,mime,dpi,target,{minQuality:.35,maxQuality:.94,allowResize:false},'resized-image',[{ok:true,label:`Physical size: ${w} × ${h} ${unit}`},{ok:true,label:`Pixels: ${dw} × ${dh}`},{ok:true,label:`DPI: ${dpi}`}]);
}
async function processDpi(){
 if(!source)throw new Error('Upload an image first.');const targetDpi=nval('dpi',300),mode=val('mode','metadata'),mime=C.mimeFromFormat(val('format','keep'),source.type);let dw=source.width,dh=source.height;if(mode==='physical'){const old=source.dpi.x||96;dw=Math.round(source.width/old*targetDpi);dh=Math.round(source.height/(source.dpi.y||old)*targetDpi);if(dw>9000||dh>9000)throw new Error('The selected DPI would create an image larger than 9,000 px per side.');}
 const canvas=C.canvas(dw,dh),ctx=canvas.getContext('2d');ctx.drawImage(source.img,0,0,dw,dh);let blob=await C.toBlob(canvas,mime,/jpeg|webp/.test(mime)?.94:undefined);if(/jpeg|png/.test(mime))blob=await C.patchDpi(blob,mime,targetDpi);lastBlob=blob;lastName=outputName('dpi-'+targetDpi,mime);if(preview)C.previewBlob(blob,preview);if(result)result.hidden=false;if(checklist)checklist.innerHTML=`<li class="pass"><b>✓</b><span>Output: ${dw} × ${dh} px</span></li><li class="pass"><b>✓</b><span>DPI: ${targetDpi}${/webp/.test(mime)?' (physical-size mode recommended for WebP)':''}</span></li><li class="pass"><b>✓</b><span>Mode: ${mode==='metadata'?'metadata / pixel dimensions preserved':'physical size preserved / resampled'}</span></li><li class="pass"><b>✓</b><span>File size: ${C.humanBytes(blob.size)}</span></li>`;msg('DPI result ready.','ok');return {blob};
}
async function processCompress(){
 if(!source)throw new Error('Upload an image first.');const targetVal=nval('target');if(targetVal<=0)throw new Error('Enter a target file size.');const unit=val('sizeunit','kb'),targetBytes=targetVal*(unit==='mb'?1048576:1024),mime=C.mimeFromFormat(val('format','jpg'),source.type),canvas=C.canvas(source.width,source.height),ctx=canvas.getContext('2d');ctx.drawImage(source.img,0,0);const floor=C.clamp(nval('qualityfloor',35)/100,.15,.9),allow=checked('allowresize'),rec=await finalize(canvas,mime,source.dpi.x||null,targetBytes,{minQuality:floor,maxQuality:.95,allowResize:allow},'compressed-image',[{ok:true,label:`Original: ${C.humanBytes(source.size)}`},{ok:true,label:`Target mode: ${val('targetmode','max')==='max'?'maximum size':'target size'}`}]);if(checklist&&lastBlob){const reduction=Math.max(0,(1-lastBlob.size/source.size)*100);checklist.insertAdjacentHTML('beforeend',`<li class="pass"><b>✓</b><span>Reduction: ${reduction.toFixed(1)}%</span></li>`);}return rec;
}
async function process(){if(busy)return;busy=true;run&&run.setAttribute('disabled','');error('');setProgress(12,'Preparing…');try{if(tool==='universal')await processUniversal();else if(tool==='signature')await processSignature();else if(tool==='photo-35x45'||tool==='photo-2x2')await processPhoto(tool);else if(tool==='physical-resizer')await processPhysical();else if(tool==='dpi-changer')await processDpi();else if(tool==='exact-compressor')await processCompress();}catch(e){hideProgress();error(e.message||'Something went wrong.');}finally{busy=false;run&&run.removeAttribute('disabled');}}
if(run)run.addEventListener('click',process);
if(download)download.addEventListener('click',()=>{if(lastBlob)C.download(lastBlob,lastName);});
if(reset)reset.addEventListener('click',()=>{if(source)C.releaseImage(source);source=null;lastBlob=null;if(file)file.value='';if(orig)orig.hidden=true;if(result)result.hidden=true;error('');msg('Ready for a new file.');if(preview&&preview.dataset.objectUrl){URL.revokeObjectURL(preview.dataset.objectUrl);delete preview.dataset.objectUrl;preview.removeAttribute('src');}});
})();
